import {carCorners} from './simulation.js?v=11';
// Minimum translation vector for two oriented vehicle/building footprints.
export function contactManifold(a,b){
 if(b.destroyed)return null;const A=carCorners(a,a.hx??.88,a.hz??2.2),B=carCorners({...b,yaw:b.yaw||0},b.hx??.88,b.hz??2.2);let best=null;
 for(const poly of [A,B])for(let i=0;i<2;i++){const p=poly[i],q=poly[i+1],len=Math.hypot(q.x-p.x,q.z-p.z),ax=-(q.z-p.z)/len,az=(q.x-p.x)/len;const pa=A.map(v=>v.x*ax+v.z*az),pb=B.map(v=>v.x*ax+v.z*az),loA=Math.min(...pa),hiA=Math.max(...pa),loB=Math.min(...pb),hiB=Math.max(...pb);if(hiA<=loB||hiB<=loA)return null;const left=hiA-loB,right=hiB-loA,depth=Math.min(left,right),sign=left<right?-1:1;if(!best||depth<best.depth)best={nx:ax*sign,nz:az*sign,depth};}return best;
}
export function separateContact(state,other){const hit=contactManifold(state,other);if(!hit)return null;const vx=-Math.sin(state.yaw)*state.speed,vz=-Math.cos(state.yaw)*state.speed,ox=-Math.sin(other.yaw||0)*(other.speed||0),oz=-Math.cos(other.yaw||0)*(other.speed||0);const inward=vx*hit.nx+vz*hit.nz;hit.impactSpeed=Math.max(0,-((vx-ox)*hit.nx+(vz-oz)*hit.nz));state.x+=hit.nx*(hit.depth+.025);state.z+=hit.nz*(hit.depth+.025);if(inward<0)state.speed=0;return hit;}
export function separateBarrier(state,info){if(!info.road.hasEdgeBarrier&&(!info.road.highway||!info.road.hasBarrier(info.d)))return null;const heading=-Math.sin(state.yaw)*info.tx-Math.cos(state.yaw)*info.tz,half=.88*Math.abs(heading)+2.2*Math.sqrt(Math.max(0,1-heading*heading)),side=info.side,sign=Math.sign(side)||-1,min=half+.38,max=info.road.widthAt(info.d)/2-half-.16;let target;if(!info.road.hasEdgeBarrier&&Math.abs(side)<min)target=sign*min;else if(Math.abs(side)>max)target=sign*max;else return null;const delta=target-side,nx=-info.tz*Math.sign(delta),nz=info.tx*Math.sign(delta),inward=(-Math.sin(state.yaw)*nx-Math.cos(state.yaw)*nz)*state.speed;state.x+=-info.tz*delta;state.z+=info.tx*delta;if(inward<0)state.speed=0;return {nx,nz,depth:Math.abs(delta),impactSpeed:Math.max(0,-inward)};}
